            "niv": "David said to him, \"Let me have the site of your threshing floor so I can build an altar to the Lord , that the plague on the people may be stopped. Sell it to me at the full price.\"",
            "esv": "And David said to Ornan, “Give me the site of the threshing floor that Imay build on it an altar to the LORD—give it to me at its full price— that the plague may be averted from the people.”"
