            "esv": "For David said, “Solomon my son is young and inexperienced, and the house that is to be built for the LORD must be exceedingly magnificent, of fame and glory throughout all lands. Iwill therefore make preparation for it.” So David provided materials in great quantity before his death. Solomon Charged to Build the Temple"
